(() => {
  'use strict';
  const messages = {"zh-CN":{"meta.description":"HadesScience 的虚拟生活记录：Create Train、Minecraft 铁路与建筑、游戏旅程、角色模型和工具实验。","skip":"跳到正文","home":"HadesScience 首页","nav.label":"主导航","nav.manifesto":"关于我","nav.missions":"探索计划","nav.contact":"联络站","nav.guestbook":"留言板","nav.open":"打开导航","nav.close":"关闭导航","hero.kicker":"好奇心，是唯一的推进剂。","hero.intro":"我是 HadesScience。","hero.line1":"在游戏里旅行，也亲手构筑世界。","hero.line2":"把创造、折腾与难忘的片段，留在这里。","hero.art":"深空蓝轨道与橙色圆盘构成的动态航天海报","hero.scrollLabel":"向下阅读个人介绍","manifesto.caption":"玩家 · 整合包作者 · 数字世界的记录者","manifesto.title1":"世界很大。","manifesto.title2":"别停在","manifesto.title3":"已知之内。","manifesto.lead1":"有些世界值得走进去。","manifesto.lead2":"有些世界，值得亲手建起来。","manifesto.body":"我是 HadesScience，也使用 Milo 这个名字。我是玩家，也是 Minecraft 整合包 Create Train 的作者。铺铁路、接传动、试模组，或只是坐上列车，看自己一点点搭起来的世界从窗外经过——这些都是我的虚拟生活。","manifesto.station":"这里存放我的虚拟生活：建造与生存、游戏实况、角色还原，以及让这些体验继续运转的工具实验。B 站、YouTube、X 与代码仓库，记录着同一个我在不同数字世界里的足迹。","principle.explore":"EXPLORE / 探索","principle.build":"CONSTRUCT / 构筑","principle.create":"REIMAGINE / 重想","missions.caption":"虚拟生活里的作品、旅程与实验","missions.intro":"从一份长期游玩的存档，到一段舍不得结束的故事，再到一次未必成功的模型实验。这里记录我已经走过的路，也留下继续折腾的方向。","missions.label":"选择探索计划","build.tab":"方块与机械","explore.tab":"游戏与旅程","create.tab":"角色与重构","build.art":"深空蓝工业构成图，机械齿轮缓慢转动","build.title1":"让想象","build.title2":"开始运转。","build.body":"Create Train 是我持续开发的 Minecraft 整合包。铁路、机械动力、自动化与模组生存，是这个世界的骨架；空中路网、移动工厂和一次次探索，则让存档慢慢有了自己的历史。开发整合包，也亲自进去玩，是同一件事的两面。","build.modrinth":"下载 Create Train","build.github":"服务端项目","explore.title1":"下一站，","explore.title2":"另一个世界。","explore.body":"科幻、沉浸叙事与动作 RPG，是我经常停留的地方。我会认真走完一段故事，也会保留旅途中普通的一刻：V 的早晨、一段同行、一次通关。游戏结束以后，人物和选择留下的感受还会继续。","game.city":"城市 / 叙事","game.action":"动作 / 哲思","game.world":"世界 / 故事","game.puzzle":"空间 / 解谜","game.space":"星海 / 探索","explore.cta":"观看 B 站游戏记录","create.title1":"把喜欢的世界，","create.title2":"换一种方式重构。","create.body":"喜欢一个角色或世界，我也会想换一种方式靠近它。在 Minecraft 里还原《圣斗士星矢》的黄金十二宫，或尝试把神里绫人的参考模型转为 YSM 适用的形式，都是把喜爱变成数字创作的过程。","create.detail":"这里保留建筑还原与 AI 辅助模型实验的记录。参考素材、工具辅助和自己的尝试各有来源；过程中的截图是探索记录，不等于模型已经完成或发布。","create.youtube":"YouTube 频道主页","contact.title1":"建立","contact.title2":"连接。","contact.intro":"在不同的平台，继续同一场探索。","search.label":"查找平台或关键词","search.placeholder":"查找平台 / 关键词","channel.code":"CODE / 个人主页","channel.build":"BUILD / 作者主页","channel.watch":"WATCH / 个人主页","channel.social":"SOCIAL / 个人主页","search.empty":"没有找到这个频道。","search.reset":"重置搜索","channel.note":"六个平台均直达个人主页，所有外链在新标签页打开。","guest.title1":"留下","guest.title2":"一条讯息。","guest.intro1":"关于游戏、创作，或只是打声招呼。","guest.intro2":"每一次交流，都可能是新探索的起点。","guest.write":"在这里写留言","guest.notice":"首次留言需完成 GitHub 登录授权，随后即可在页内编辑器中输入、预览和发布。留言会公开展示，请勿填写私人信息。","guest.thread":"查看完整讨论","guest.editorTitle":"写一条讯息","guest.connecting":"正在连接页内留言编辑器…","guest.retryEditor":"重新连接留言编辑器","guest.readback":"查看留言列表与备用入口","guest.refresh":"刷新留言","guest.idle":"滚动至此，读取公开留言。","guest.empty":"还没有留言。","guest.first":"第一条讯息，或许就来自你。","guest.public":"公开留言","guest.more":"继续读取留言","guest.order":"按发布时间排列 · 留言长期保存在 GitHub","guest.github":"前往 GitHub 留言","noscript.please":"请","noscript.github":"前往 GitHub 查看和发布留言","noscript.note":"页面导航与外链均可使用；探索计划全部展示。频道搜索和网页内的留言读取需要启用 JavaScript。","search.heading":"FIND A CHANNEL","channel.directory":"CHANNEL DIRECTORY","hero.scroll":"SCROLL TO DISCOVER","footer.top":"BACK TO TOP","lang.label":"选择语言","lang.auto":"跟随浏览器","search.count":"{shown} / {total} 个频道","guest.anonymous":"已注销用户","guest.visitor":"访客","guest.permalink":"在 GitHub 查看 {name} 的留言","guest.loading":"正在读取公开留言…","guest.rateLimit":"GitHub 暂时限制了读取频率。请稍后刷新，或前往 GitHub 查看留言。","guest.loadError":"暂时无法读取留言。请刷新重试，或前往 GitHub 查看完整讨论。","guest.dataError":"留言数据暂时不可用，请稍后重试。","guest.loaded":"已读取 {count} 条公开留言","guest.connected":"公开频道已连接。","guest.timeout":"读取超时。请刷新重试，或前往 GitHub 查看留言。","guest.network":"网络连接暂时不可用，请刷新重试，或前往 GitHub 查看留言。","guest.ready":"完成 GitHub 登录授权后，即可在下方编辑、预览和发布。","guest.editorError":"留言编辑器暂时无法连接。请重试，或展开下方备用入口。","records.projects":"整合包、机械与存档记录","record.train.kind":"整合包 / 铁路与自动化","record.train.body":"以 Create 铁路为中心，组合机械、角色模型与生存内容，构建可以长期探索的模组世界。","record.guided.kind":"模组 / 启动引导","record.guided.body":"为整合包制作首次启动引导、模式选择与可选模组开关，让玩家更清楚地选择自己的体验。","record.sorcery.kind":"整合包 / 机械与魔法","record.sorcery.body":"让 Create 6 与 Ars Nouveau 相遇，在机械生产、魔法与冒险之间，寻找另一种生存节奏。","record.modrinth":"在 Modrinth 查看","records.games":"留下来的游戏片段","record.cyber.kind":"游戏实况 / 叙事","record.cyber.title":"夜之城，太阳结局","record.cyber.body":"《赛博朋克 2077》太阳结局的完整流程记录，保留这一段旅程。","record.nier.title":"NieR:Automata，一周目终点","record.nier.body":"记录《尼尔：机械纪元》第一周目的收尾，关于旅途，也关于余韵。","record.watch":"观看视频","create.bilibili":"B 站实况、实验与创作","records.videos":"建筑还原与角色实验","record.series.kind":"系列 / 生存实况","record.series.title":"Create Train 实况","record.series.body":"从新的征程到继续开拓，把整合包里的生存与探索串成连续记录。","record.test.kind":"实验 / 性能对比","record.test.title":"有 C2ME，与没有 C2ME","record.test.body":"记录高速飞行时的区块加载对比。YouTube 版简介列出 Minecraft 1.20.1、Forge 47.4.1 与 270 多个模组的测试环境。","record.temple.kind":"创作 / 建筑还原","record.temple.title":"在 Minecraft 还原黄金十二宫","record.temple.body":"把《圣斗士星矢》中的圣域建筑转化为方块世界里的空间。","tools.tab":"代码与工具","tools.title1":"从问题出发，","tools.title2":"做一个工具。","tools.body":"遇到工具不顺手、工作流衔接不上，或兼容性出了问题，我也会尝试自己动手处理。这里放着一些实际问题带来的适配与修复，以及留给后来使用者的说明。","tools.detail":"独立工具、基于上游的适配，以及开源项目的分支实验，是不同的参与方式。具体实现和来源都留在仓库中。","tools.art":"由节点、连线与几何模块组成的代码工作流图","tools.github":"更多公开代码","records.tools":"测试、适配与修复记录","record.browser.kind":"适配 / 基于上游项目","record.browser.body":"将 Browser Use CLI 工作流封装为 Codex 插件，补充 Windows PowerShell 使用说明。浏览器能力来自上游项目。","record.fixer.kind":"工具 / 兼容性修复","record.fixer.body":"面向 Windows 上的 CC Switch 与 Gemini 工具调用兼容问题制作的修复工具，原理与使用方式记录在仓库。","record.source":"查看代码与说明","record.factory.kind":"演示 / 机械系统","record.factory.title":"移动工厂：底盘与动力","record.factory.body":"既然可以把材料送到工厂，为什么不能开着工厂去找材料？记录大型履带移动工厂的底盘与动力设计。","focus.label":"我在意的事","focus.browse":"浏览这一方向的作品","focus.build.title":"从一段传动，到一整条铁路。","focus.build.first.title":"让世界真正运转起来","focus.build.first.body":"把矿区旧线改成空中高速铁路，坐上环林线看沿途风景，或者干脆开着工厂去找材料。比起一件孤立的机器，我更喜欢把线路、动力与用途连成一个能游玩的系统。","focus.build.second.title":"把存档里的日子留下来","focus.build.second.body":"Create Train 实况从发现城堡、飞向远方，记录到探索与归途；存档一周年也值得单独留念。接下来仍想继续建设、继续游玩，把成功的设计和意外的翻车都留下。","focus.explore.title":"有些游戏结束了，旅程还没有。","focus.explore.first.title":"会记住故事里的人","focus.explore.first.body":"在《赛博朋克 2077》里，我喜欢帕南，也偏爱星星结局。吸引我的不只是世界的规模，还有人物、关系与选择留下的感受。","focus.explore.second.title":"通关以后，仍然想起","focus.explore.second.body":"《PRAGMATA》让我为真结局继续努力，也记住了“去看大海吧”；《尼尔：机械纪元》的一周目终点，则留下另一种余韵。解开《传送门 2》的空间、继续探索《无人深空》，也是这份好奇心的去处。","focus.create.title":"从圣域的台阶，到模型的轮廓。","focus.create.first.title":"用方块留住一个熟悉的世界","focus.create.first.body":"黄金十二宫的还原，连接了我对《圣斗士星矢》和 Minecraft 的喜爱。柱廊、台阶与宫殿的轮廓，让原本在作品里见过的空间，变成可以自己走进去的地方。","focus.create.second.title":"试着把角色带进另一个游戏","focus.create.second.body":"我尝试让 AI 通过 MCP 连接 Blender 与 Blockbench，参考已有模型和三视图，探索 YSM 模型、UV 与骨骼适配。这条路线仍是实验；想继续弄清楚工具能做到哪里，也把尝试的过程留下。","focus.tools.title":"有个问题，那就试着把它解决。","focus.tools.first.title":"工具要能用在自己的环境里","focus.tools.first.body":"Browser Use for Codex 是围绕上游浏览器工具做的适配封装。我关注它如何进入日常工作流，也整理 Windows PowerShell 下的使用细节。","focus.tools.second.title":"解决了，也把过程说明白","focus.tools.second.body":"CC Switch Gemini Fixer 来自具体的兼容问题。把修复方式与使用说明留在仓库，是为了让一次折腾留下可以继续使用的东西。","about.journeys":"我也会在夜之城记住一个人，为一段结局反复回味，或在通关后久久不想离开。科幻、沉浸叙事与能自由探索的系统总能吸引我。从《赛博朋克 2077》到《尼尔：机械纪元》与《PRAGMATA》，我想留下的不只有通关记录，还有故事结束后的余韵。","record.rail.kind":"存档 / 铁路运行","record.rail.title":"沉浸式搭乘空中高速铁路","record.rail.body":"由早期矿区线路改扩建而来。视频记录时已有 5 站、10 站台，8 列六节编组列车运行；从乘客视角看看这个世界。","record.panam.title":"和帕南一行，前往荒坂塔","record.panam.body":"保留与帕南一行同行的游戏实况。星星是我偏爱的结局；这段记录留下走向那个结局的旅程。","record.pragmata.title":"PRAGMATA：通关之后","record.pragmata.body":"从预购到通关，再为真结局继续努力。“去看大海吧”留在了心里；游戏告一段落，感受还没有。","record.model.kind":"实验 / AI 辅助模型","record.model.title":"神里绫人 × YSM：适配尝试","record.model.body":"以已有模型和三视图为参考，尝试用 AI、Blender 与 Blockbench 探索 YSM 适配。链接是过程记录，并非成品下载。","record.process":"查看实验记录","record.reflection":"阅读通关感想","theme.toggle":"切换主题风格","theme.mineral":"深空矿物","theme.ivory":"至上米白"},"en":{"meta.description":"HadesScience’s digital life: Create Train, Minecraft railways and builds, game journeys, character models and tool experiments.","skip":"Skip to content","home":"HadesScience home","nav.label":"Main navigation","nav.manifesto":"About me","nav.missions":"Missions","nav.contact":"Connect","nav.guestbook":"Guestbook","nav.open":"Open navigation","nav.close":"Close navigation","hero.kicker":"Curiosity is the only propellant.","hero.intro":"I'm HadesScience.","hero.line1":"Travelling through games. Building worlds of my own.","hero.line2":"Keeping the builds, experiments and moments that stay with me.","hero.art":"Animated space poster with deep blue orbits and an orange disc","hero.scrollLabel":"Read my introduction","manifesto.caption":"PLAYER · MODPACK CREATOR · DIGITAL WORLDS","manifesto.title1":"A vast world.","manifesto.title2":"Go beyond","manifesto.title3":"the familiar.","manifesto.lead1":"Some worlds are worth stepping into.","manifesto.lead2":"Others are worth building yourself.","manifesto.body":"I’m HadesScience, also known as Milo: a player and the creator of the Minecraft modpack Create Train. Laying rails, connecting machinery, trying mods, or simply watching a world I’ve built pass by a train window—these are parts of my digital life.","manifesto.station":"This is an archive of my digital life: builds and survival, playthroughs, character recreations and the tool experiments behind them. Bilibili, YouTube, X and my repositories hold different parts of the same journey.","principle.explore":"EXPLORE","principle.build":"CONSTRUCT","principle.create":"REIMAGINE","missions.caption":"BUILDS, JOURNEYS AND EXPERIMENTS IN DIGITAL WORLDS","missions.intro":"From a long-running save to a story I don’t want to leave, or a model experiment that may not work out. These are the paths I’ve taken and the things I want to keep trying.","missions.label":"Choose a mission","build.tab":"Blocks & machines","explore.tab":"Games & journeys","create.tab":"Characters & worlds","build.art":"Deep blue industrial composition with slowly rotating gears","build.title1":"Set ideas","build.title2":"in motion.","build.body":"Create Train is the Minecraft modpack I keep developing. Railways, Create machinery, automation and modded survival form its framework. Sky railways, a moving factory and ongoing exploration give the save its own history. Making the pack and playing it go together.","build.modrinth":"Get Create Train","build.github":"Server pack project","explore.title1":"Next stop:","explore.title2":"another world.","explore.body":"Science fiction, immersive stories and action RPGs are where I often linger. I follow stories through, but also keep ordinary moments: V’s morning, time with companions, the end of a playthrough. The people and choices stay after the game ends.","game.city":"CITY / STORY","game.action":"ACTION / IDEAS","game.world":"WORLD / STORY","game.puzzle":"SPACE / PUZZLES","game.space":"STARS / EXPLORATION","explore.cta":"Watch my game recordings","create.title1":"Worlds I love,","create.title2":"recreated in another form.","create.body":"When I love a character or world, I want to explore it in another form. Recreating Saint Seiya’s Twelve Zodiac Temples in Minecraft, or experimenting with adapting a Kamisato Ayato reference model for YSM, turns that affection into digital creation.","create.detail":"These are records of architectural recreations and AI-assisted model experiments. Reference material, tool assistance and my own attempts each have their place. Progress screenshots document exploration, not a finished or released model.","create.youtube":"YouTube channel","contact.title1":"Make","contact.title2":"contact.","contact.intro":"Continue the same journey across different platforms.","search.label":"Find a platform or keyword","search.placeholder":"Platform / keyword","channel.code":"CODE / PROFILE","channel.build":"BUILD / CREATOR","channel.watch":"WATCH / PROFILE","channel.social":"SOCIAL / PROFILE","search.empty":"No matching channels.","search.reset":"Reset search","channel.note":"All six channels link directly to my profiles. External links open in a new tab.","guest.title1":"Send","guest.title2":"a message.","guest.intro1":"Talk games, share ideas, or just say hello.","guest.intro2":"Every conversation can start a new exploration.","guest.write":"Write a message","guest.notice":"Sign in and authorize with GitHub to write, preview and post here. Messages are public. Do not include private information.","guest.thread":"View full discussion","guest.editorTitle":"Write a message","guest.connecting":"Connecting the message editor…","guest.retryEditor":"Reconnect editor","guest.readback":"Message list and alternative links","guest.refresh":"Refresh messages","guest.idle":"Open this panel to read public messages.","guest.empty":"No messages yet.","guest.first":"The first signal could be yours.","guest.public":"Public messages","guest.more":"Load more messages","guest.order":"In posting order · Messages are stored on GitHub","guest.github":"Comment on GitHub","noscript.please":"Please ","noscript.github":"read and post messages on GitHub","noscript.note":"Navigation and external links work without JavaScript, and all missions remain visible. Channel search and inline messages require JavaScript.","search.heading":"FIND A CHANNEL","channel.directory":"CHANNEL DIRECTORY","hero.scroll":"SCROLL TO DISCOVER","footer.top":"BACK TO TOP","lang.label":"Choose language","lang.auto":"Browser default","search.count":"{shown} / {total} CHANNELS","guest.anonymous":"Deleted user","guest.visitor":"visitor","guest.permalink":"View {name}'s message on GitHub","guest.loading":"Loading public messages…","guest.rateLimit":"GitHub has temporarily limited requests. Try again later or view the discussion on GitHub.","guest.loadError":"Messages could not be loaded. Retry or view the full discussion on GitHub.","guest.dataError":"Message data is unavailable. Please try again later.","guest.loaded":"{count} public messages loaded","guest.connected":"Public channel connected.","guest.timeout":"The request timed out. Retry or view messages on GitHub.","guest.network":"The network is unavailable. Retry or view messages on GitHub.","guest.ready":"Sign in with GitHub to write, preview and post below.","guest.editorError":"The editor could not connect. Retry or use the alternative links below.","records.projects":"Modpacks, machines and life in a save","record.train.kind":"MODPACK / RAILWAYS & AUTOMATION","record.train.body":"A Create railway modpack bringing machinery, player models and survival content into one world to explore.","record.guided.kind":"MOD / FIRST-LAUNCH GUIDE","record.guided.body":"A first-launch guide with mode selection and optional mod toggles, helping players choose their modpack experience.","record.sorcery.kind":"MODPACK / MACHINES & MAGIC","record.sorcery.body":"Create 6 meets Ars Nouveau: a different survival rhythm between mechanical production, magic and adventure.","record.modrinth":"View on Modrinth","records.games":"Moments from other worlds","record.cyber.kind":"GAMEPLAY / STORY","record.cyber.title":"Night City: The Sun ending","record.cyber.body":"A full recording of The Sun ending in Cyberpunk 2077, preserving the journey.","record.nier.title":"NieR:Automata, first playthrough","record.nier.body":"The closing moments of my first NieR:Automata playthrough: a journey and its afterglow.","record.watch":"Watch video","create.bilibili":"Bilibili playthroughs, experiments & creations","records.videos":"Architecture and character experiments","record.series.kind":"SERIES / SURVIVAL","record.series.title":"Create Train playthrough","record.series.body":"A survival and exploration series following new journeys through the modpack.","record.test.kind":"EXPERIMENT / PERFORMANCE","record.test.title":"With C2ME / Without C2ME","record.test.body":"A chunk-loading comparison during high-speed flight. The YouTube description lists Minecraft 1.20.1, Forge 47.4.1 and more than 270 mods as the test setup.","record.temple.kind":"BUILD / RECREATION","record.temple.title":"The Twelve Temples in Minecraft","record.temple.body":"Recreating Saint Seiya sanctuary architecture as spaces in a world of blocks.","tools.tab":"Code & tools","tools.title1":"Start with a problem.","tools.title2":"Build a tool.","tools.body":"When tools feel awkward, workflows do not connect or compatibility breaks, I try working on the problem myself. These are adaptations and fixes prompted by practical needs, with instructions for the next person who uses them.","tools.detail":"Standalone utilities, upstream-based adaptations and fork experiments are different kinds of work. Their implementation and origins are documented in the repositories.","tools.art":"A code workflow diagram of connected nodes and geometric modules","tools.github":"More public code","records.tools":"Tests, adaptations and fixes","record.browser.kind":"ADAPTATION / BUILT ON UPSTREAM","record.browser.body":"Packages Browser Use CLI workflows as a Codex plugin, with Windows PowerShell guidance. Browser automation is provided by the upstream projects.","record.fixer.kind":"UTILITY / COMPATIBILITY","record.fixer.body":"A utility for CC Switch and Gemini tool-call compatibility on Windows. The repository documents its approach and usage.","record.source":"Code & documentation","record.factory.kind":"DEMO / MECHANICAL SYSTEMS","record.factory.title":"Moving factory: chassis & power","record.factory.body":"If materials can travel to the factory, why not drive the factory to them? A record of the chassis and power system of a large tracked mobile factory.","focus.label":"What matters to me","focus.browse":"Browse work in this field","focus.build.title":"From a moving gear to an entire railway.","focus.build.first.title":"A world that actually runs","focus.build.first.body":"Rebuild an old mining line as a sky railway, ride the forest loop for the view, or drive the factory to the materials. I enjoy connecting routes, power and purpose into a playable system.","focus.build.second.title":"Keeping the life of a save","focus.build.second.body":"The Create Train series follows castles, flights, exploration and the journey home. Even a save’s first anniversary deserves a record. I want to keep building and playing, keeping the designs that work and the mishaps along the way.","focus.explore.title":"A game can end before its journey leaves you.","focus.explore.first.title":"The people in the story stay with me","focus.explore.first.body":"In Cyberpunk 2077, I like Panam and prefer the Star ending. What draws me in is not just the scale of a world, but its people, relationships and the feelings its choices leave behind.","focus.explore.second.title":"What stays after the credits","focus.explore.second.body":"PRAGMATA kept me working towards its true ending; “Go see the ocean” stayed with me. NieR:Automata’s first-route ending left a different echo. Portal 2’s spaces and No Man’s Sky’s horizons give that same curiosity somewhere else to go.","focus.create.title":"From temple steps to a model’s silhouette.","focus.create.first.title":"A familiar world, built in blocks","focus.create.first.body":"The Twelve Zodiac Temples connect my love of Saint Seiya with Minecraft. Colonnades, steps and palace silhouettes turn a place I knew from fiction into somewhere I can walk through.","focus.create.second.title":"Trying a character in another game","focus.create.second.body":"I’ve tried connecting Blender and Blockbench to AI through MCP, using existing models and reference views to explore YSM geometry, UVs and rigging. It remains an experiment: I want to find the tools’ limits and keep a record of the attempts.","focus.tools.title":"There is a problem. Let’s try solving it.","focus.tools.first.title":"Tools should fit the environment I use","focus.tools.first.body":"Browser Use for Codex packages an adaptation of upstream browser tools. I focus on fitting it into everyday workflows and document the details of using it in Windows PowerShell.","focus.tools.second.title":"Explain the fix as well as making it","focus.tools.second.body":"CC Switch Gemini Fixer grew from a specific compatibility problem. Keeping the fix and instructions in the repository means the effort leaves something reusable.","about.journeys":"I remember people in Night City, return to endings and sometimes linger long after the credits. Science fiction, immersive stories and systems I can explore draw me in. From Cyberpunk 2077 to NieR:Automata and PRAGMATA, I want to keep more than a record of finishing a game: I want to keep what it left with me.","record.rail.kind":"Save / railway operation","record.rail.title":"A ride on the sky railway","record.rail.body":"Rebuilt from an early mining line. At the time of recording: 5 stations, 10 platforms and 8 six-car trains. See the world from a passenger’s seat.","record.panam.title":"To Arasaka Tower with Panam","record.panam.body":"A playthrough alongside Panam and her companions. The Star is my preferred ending; this recording keeps part of the journey towards it.","record.pragmata.title":"PRAGMATA: after the ending","record.pragmata.body":"From preorder to completion, then onwards to the true ending. “Go see the ocean” stayed with me. The game ends; the feeling doesn’t.","record.model.kind":"Experiment / AI-assisted models","record.model.title":"Kamisato Ayato × YSM: adaptation experiments","record.model.body":"Using existing models and reference views to explore YSM adaptation with AI, Blender and Blockbench. The link documents the process, not a finished model download.","record.process":"View experiment notes","record.reflection":"Read my reflections","theme.toggle":"Toggle theme","theme.mineral":"MINERAL","theme.ivory":"IVORY"},"ja":{"meta.description":"HadesScienceのデジタル世界の記録。Create Train、Minecraftの鉄道と建築、ゲームの旅、キャラクターモデル、ツールの実験。","skip":"本文へ移動","home":"HadesScience ホーム","nav.label":"メインナビゲーション","nav.manifesto":"私について","nav.missions":"探求計画","nav.contact":"つながる","nav.guestbook":"ゲストブック","nav.open":"メニューを開く","nav.close":"メニューを閉じる","hero.kicker":"好奇心こそ、唯一の推進力。","hero.intro":"HadesScienceです。","hero.line1":"ゲームを旅し、自分の手で世界を築く。","hero.line2":"創作も、試行錯誤も、忘れられない場面も、ここに。","hero.art":"深宇宙ブルーの軌道とオレンジの円盤が動く宇宙ポスター","hero.scrollLabel":"自己紹介へスクロール","manifesto.caption":"プレイヤー · モッドパック制作者 · 世界の記録","manifesto.title1":"世界は広い。","manifesto.title2":"その先の","manifesto.title3":"未知へ。","manifesto.lead1":"足を踏み入れたい世界がある。","manifesto.lead2":"自分の手で築きたい世界もある。","manifesto.body":"HadesScience、またの名をMilo。プレイヤーであり、MinecraftのモッドパックCreate Trainの作者です。線路を敷き、機械をつなぎ、モッドを試す。ときには列車に乗り、少しずつ築いた世界を窓から眺める。それも私のゲームの時間です。","manifesto.station":"ここに残すのは、建築とサバイバル、プレイ記録、キャラクターの再現、それらを支えるツールの実験。Bilibili、YouTube、X、コードのリポジトリに、同じ私の旅の記録がつながっています。","principle.explore":"EXPLORE / 探求","principle.build":"CONSTRUCT / 構築","principle.create":"REIMAGINE / 再創造","missions.caption":"デジタル世界での創作、旅、実験","missions.intro":"長く遊び続けるセーブデータ、終わってほしくない物語、うまくいくとは限らないモデル実験。歩んだ道と、これからも試したいことを記録しています。","missions.label":"探求計画を選ぶ","build.tab":"ブロックと機械","explore.tab":"ゲームと旅","create.tab":"キャラクターと再現","build.art":"歯車がゆっくり回る深宇宙ブルーの工業構成図","build.title1":"想像を","build.title2":"動かそう。","build.body":"Create Trainは開発を続けているMinecraftのモッドパックです。鉄道、Createの機械、自動化、モッド入りのサバイバルが土台。空中路線や移動工場、探索の積み重ねが、セーブデータに歴史をつくります。制作することと、自分で遊ぶことはつながっています。","build.modrinth":"Create Train を入手","build.github":"サーバーパック","explore.title1":"次の行き先は、","explore.title2":"別の世界。","explore.body":"SF、没入できる物語、アクションRPGによく足を止めます。物語を最後まで追いながら、Vの朝、仲間との道中、クリアの瞬間も残す。ゲームが終わっても、人物や選択の余韻は続きます。","game.city":"都市 / 物語","game.action":"アクション / 思索","game.world":"世界 / 物語","game.puzzle":"空間 / パズル","game.space":"星々 / 探索","explore.cta":"Bilibili のプレイ記録","create.title1":"好きな世界を、","create.title2":"別の形で再現する。","create.body":"好きなキャラクターや世界には、別の形でも触れてみたくなります。Minecraftで聖闘士星矢の黄金十二宮を再現したり、神里綾人の参考モデルをYSM向けに変換する実験をしたり。好きという気持ちをデジタルの創作につなげています。","create.detail":"建築再現とAIを使ったモデル実験の記録です。参考素材、ツールの補助、自分の試行は、それぞれの出所を大切にしています。作業中の画像は、モデルの完成や公開を示すものではありません。","create.youtube":"YouTube チャンネル","contact.title1":"つながりを","contact.title2":"つくろう。","contact.intro":"場所を変えても、探求は続く。","search.label":"プラットフォームやキーワードを検索","search.placeholder":"プラットフォーム / キーワード","channel.code":"CODE / プロフィール","channel.build":"BUILD / 作者ページ","channel.watch":"WATCH / プロフィール","channel.social":"SOCIAL / プロフィール","search.empty":"該当するチャンネルはありません。","search.reset":"検索をリセット","channel.note":"六つのリンクはすべて本人のページへ。外部リンクは新しいタブで開きます。","guest.title1":"メッセージを","guest.title2":"残そう。","guest.intro1":"ゲームや創作の話でも、ひとことの挨拶でも。","guest.intro2":"どんな会話も、新たな探求の始まりになる。","guest.write":"ここに書き込む","guest.notice":"GitHubでログイン・認証すると、ここで入力、プレビュー、投稿ができます。内容は公開されます。個人情報は書かないでください。","guest.thread":"すべてのやり取りを見る","guest.editorTitle":"メッセージを書く","guest.connecting":"投稿エディターに接続中…","guest.retryEditor":"エディターに再接続","guest.readback":"メッセージ一覧と代替リンク","guest.refresh":"メッセージを更新","guest.idle":"このパネルを開くとメッセージを読み込めます。","guest.empty":"まだメッセージはありません。","guest.first":"最初のメッセージは、あなたからかもしれない。","guest.public":"公開メッセージ","guest.more":"さらに読み込む","guest.order":"投稿順 · メッセージはGitHubに保存されます","guest.github":"GitHubで書き込む","noscript.please":"こちらから","noscript.github":"GitHubでメッセージを閲覧・投稿できます","noscript.note":"ナビゲーションと外部リンクは利用でき、すべての計画も表示されます。検索とページ内メッセージにはJavaScriptが必要です。","search.heading":"チャンネルを探す","channel.directory":"チャンネル一覧","hero.scroll":"スクロールして探る","footer.top":"ページ上部へ","lang.label":"言語を選ぶ","lang.auto":"ブラウザーに合わせる","search.count":"{shown} / {total} チャンネル","guest.anonymous":"削除されたユーザー","guest.visitor":"訪問者","guest.permalink":"{name}のメッセージをGitHubで表示","guest.loading":"メッセージを読み込み中…","guest.rateLimit":"GitHubのアクセス制限中です。後でもう一度試すか、GitHubでご覧ください。","guest.loadError":"読み込めませんでした。再試行するか、GitHubでご覧ください。","guest.dataError":"メッセージを取得できません。後でもう一度お試しください。","guest.loaded":"{count}件のメッセージを読み込みました","guest.connected":"公開チャンネルに接続しました。","guest.timeout":"読み込みがタイムアウトしました。再試行するか、GitHubでご覧ください。","guest.network":"ネットワークに接続できません。再試行するか、GitHubでご覧ください。","guest.ready":"GitHubでログイン・認証すると、下のエディターで投稿できます。","guest.editorError":"エディターに接続できません。再試行するか、下の代替リンクをご利用ください。","records.projects":"モッドパック、機械、セーブの記録","record.train.kind":"モッドパック / 鉄道・自動化","record.train.body":"Createの鉄道を中心に、機械・プレイヤーモデル・サバイバル要素を組み合わせたモッドパック。","record.guided.kind":"モッド / 初回起動ガイド","record.guided.body":"初回起動ガイド、モード選択、任意モッドの切り替えで、プレイヤーの体験選びを支えます。","record.sorcery.kind":"モッドパック / 機械と魔法","record.sorcery.body":"Create 6とArs Nouveauを組み合わせ、機械生産・魔法・冒険を行き来するサバイバルへ。","record.modrinth":"Modrinth で見る","records.games":"別の世界からのプレイ記録","record.cyber.kind":"プレイ記録 / 物語","record.cyber.title":"ナイトシティ：太陽エンディング","record.cyber.body":"『サイバーパンク2077』太陽エンディングの一部始終を記録。","record.nier.title":"NieR:Automata、最初の周回の終わり","record.nier.body":"『NieR:Automata』一周目の終わり。旅と、その余韻の記録。","record.watch":"動画を見る","create.bilibili":"Bilibili のプレイ記録・実験・創作","records.videos":"建築再現とキャラクター実験","record.series.kind":"シリーズ / サバイバル","record.series.title":"Create Train プレイ記録","record.series.body":"モッドパックの世界で続く、サバイバルと探索のシリーズ。","record.test.kind":"実験 / パフォーマンス比較","record.test.title":"C2ME あり / なし","record.test.body":"高速飛行時のチャンク読み込みを比較。YouTube版の説明にはMinecraft 1.20.1、Forge 47.4.1、270以上のモッドという環境を記載しています。","record.temple.kind":"制作 / 建築再現","record.temple.title":"Minecraft で黄金十二宮を再現","record.temple.body":"『聖闘士星矢』の聖域建築を、ブロックの世界の空間へ。","tools.tab":"コードとツール","tools.title1":"課題から始め、","tools.title2":"ツールをつくる。","tools.body":"ツールが使いづらい、作業の流れがつながらない、互換性に問題がある。そんなときには、自分でも解決を試みます。ここには実際の問題から生まれた適応や修正と、次に使う人のための説明をまとめています。","tools.detail":"独立ツール、上流プロジェクトを使った適応、フォークでの実験。それぞれの実装と出典はリポジトリに記録しています。","tools.art":"ノードと線、幾何学モジュールによるワークフロー図","tools.github":"公開コードを見る","records.tools":"テスト、適合、修正の記録","record.browser.kind":"適応 / 上流プロジェクトを活用","record.browser.body":"Browser Use CLIをCodexプラグインとしてまとめ、Windows PowerShell向けの説明を追加。ブラウザ操作は上流プロジェクトの機能です。","record.fixer.kind":"ツール / 互換性修正","record.fixer.body":"Windows版CC SwitchとGeminiのツール呼び出し互換性に対応するユーティリティ。仕組みと使い方はリポジトリに記載。","record.source":"コードと説明を見る","record.factory.kind":"実演 / 機械システム","record.factory.title":"移動工場：シャーシと動力","record.factory.body":"材料を工場へ運べるなら、工場ごと材料を探しに行ってもいい。大型履帯式移動工場の車体と動力を紹介しています。","focus.label":"私が大切にしていること","focus.browse":"この分野の作品を見る","focus.build.title":"一つの動力伝達から、鉄道全体へ。","focus.build.first.title":"世界を本当に動かす","focus.build.first.body":"鉱区の旧線を空中高速鉄道に改築し、環林線で景色を眺め、ときには工場ごと材料を探しに行く。路線、動力、用途をつないで、遊べる仕組みにするのが好きです。","focus.build.second.title":"セーブデータの日々を残す","focus.build.second.body":"城の発見、遠方への飛行、探索と帰路。Create Trainの実況で、その日々を残しています。セーブデータの一周年も大事な節目。これからも建てて遊び、成功も失敗も記録したいです。","focus.explore.title":"ゲームが終わっても、旅は心に残る。","focus.explore.first.title":"物語の中の人を覚えている","focus.explore.first.body":"『Cyberpunk 2077』ではパナムが好きで、「星」エンディングを好んでいます。世界の広さだけでなく、人物や関係、選択が残す気持ちに惹かれます。","focus.explore.second.title":"クリアしても、思い出す","focus.explore.second.body":"PRAGMATAでは真のエンディングを目指し、「海を見に行こう」という言葉が心に残りました。NieR:Automataの一周目にも、また別の余韻があります。Portal 2の空間やNo Man’s Skyの地平も、好奇心の向かう先です。","focus.create.title":"聖域の階段から、モデルの輪郭へ。","focus.create.first.title":"見慣れた世界をブロックで","focus.create.first.body":"黄金十二宮の再現は、聖闘士星矢とMinecraftへの好きが重なったもの。列柱、階段、宮殿の輪郭を通して、作品の中の空間を自分で歩ける場所にしています。","focus.create.second.title":"別のゲームへキャラクターを","focus.create.second.body":"AIからMCPでBlenderとBlockbenchをつなぎ、既存モデルや三面図を参考にYSMの形状、UV、ボーン適合を試しています。まだ実験の段階。ツールで何ができるかを確かめ、その過程も残したいです。","focus.tools.title":"問題があるなら、解決を試してみる。","focus.tools.first.title":"自分の環境で使えるツールに","focus.tools.first.body":"Browser Use for Codex は上流のブラウザーツールを適応・パッケージ化したものです。日常の作業への組み込み方と、Windows PowerShell での使い方を整理しています。","focus.tools.second.title":"直したら、過程も伝える","focus.tools.second.body":"CC Switch Gemini Fixer は具体的な互換性の問題から生まれました。修正方法と説明をリポジトリに残し、試行錯誤を再利用できる形にしています。","about.journeys":"ナイトシティで出会った人物を覚えていたり、エンディングを何度も思い返したり、クリアしても離れがたかったり。SF、没入できる物語、自由に探れる仕組みに惹かれます。Cyberpunk 2077、NieR:Automata、PRAGMATA。残したいのはクリアの記録と、その先に続く余韻です。","record.rail.kind":"セーブ / 鉄道運行","record.rail.title":"空中高速鉄道に乗る","record.rail.body":"初期の鉱区線を改築・延伸。撮影時は5駅10ホーム、6両編成8本が運行していました。乗客の視点で世界を眺めます。","record.panam.title":"パナムたちとアラサカ・タワーへ","record.panam.body":"パナムたちと進むプレイ記録。好きな結末は「星」。そこへ至る道中を残しています。","record.pragmata.title":"PRAGMATA：クリアのあとに","record.pragmata.body":"予約からクリア、そして真の結末を目指して。「海を見に行こう」が心に残りました。ゲームが一区切りついても、余韻は続きます。","record.model.kind":"実験 / AIによるモデル制作補助","record.model.title":"神里綾人 × YSM：適合の試み","record.model.body":"既存モデルと三面図を参考に、AI、Blender、BlockbenchでYSM適合を試す記録。リンク先は制作過程で、完成品の配布ではありません。","record.process":"実験の記録を見る","record.reflection":"クリア後の感想を読む","theme.toggle":"テーマ切替","theme.mineral":"深宇宙鉱物","theme.ivory":"至上アイボリー"},"ru":{"meta.description":"Цифровая жизнь HadesScience: Create Train, железные дороги и постройки в Minecraft, игровые путешествия, модели персонажей и эксперименты с инструментами.","skip":"Перейти к содержимому","home":"Главная HadesScience","nav.label":"Основная навигация","nav.manifesto":"Обо мне","nav.missions":"Проекты","nav.contact":"Контакты","nav.guestbook":"Гостевая","nav.open":"Открыть меню","nav.close":"Закрыть меню","hero.kicker":"Любопытство — единственное топливо.","hero.intro":"Я HadesScience.","hero.line1":"Путешествую по играм и создаю свои миры.","hero.line2":"Сохраняю здесь постройки, эксперименты и памятные моменты.","hero.art":"Анимированный космический плакат с синими орбитами и оранжевым диском","hero.scrollLabel":"Перейти к рассказу обо мне","manifesto.caption":"ИГРОК · АВТОР МОДПАКОВ · ЦИФРОВЫЕ МИРЫ","manifesto.title1":"Мир огромен.","manifesto.title2":"Выходи за","manifesto.title3":"привычное.","manifesto.lead1":"В одни миры стоит войти.","manifesto.lead2":"Другие — построить самому.","manifesto.body":"Я HadesScience, также известный как Milo: игрок и автор модпака Create Train для Minecraft. Прокладываю рельсы, соединяю механизмы, пробую моды или просто смотрю из окна поезда на мир, который постепенно построил. Всё это — моя цифровая жизнь.","manifesto.station":"Здесь хранятся мои постройки, выживание, прохождения, воссоздания персонажей и эксперименты с инструментами. Bilibili, YouTube, X и репозитории сохраняют разные части одного путешествия по цифровым мирам.","principle.explore":"EXPLORE / ИССЛЕДОВАТЬ","principle.build":"CONSTRUCT / СОЗДАВАТЬ","principle.create":"REIMAGINE / ПЕРЕОСМЫСЛЯТЬ","missions.caption":"ПОСТРОЙКИ, ПУТЕШЕСТВИЯ И ЭКСПЕРИМЕНТЫ","missions.intro":"Долгий путь в одном сохранении, история, с которой не хочется расставаться, или эксперимент с моделью без гарантии успеха. Здесь — уже пройденные пути и то, что хочется пробовать дальше.","missions.label":"Выбрать направление","build.tab":"Блоки и механизмы","explore.tab":"Игры и путешествия","create.tab":"Персонажи и миры","build.art":"Синяя индустриальная композиция с медленно вращающимися шестернями","build.title1":"Привести идеи","build.title2":"в движение.","build.body":"Create Train — модпак для Minecraft, который я продолжаю развивать. Железные дороги, механизмы Create, автоматизация и выживание составляют его основу. Воздушные линии, передвижная фабрика и вылазки постепенно создают историю сохранения. Делать сборку и играть в неё для меня неразделимо.","build.modrinth":"Скачать Create Train","build.github":"Серверная сборка","explore.title1":"Следующая остановка —","explore.title2":"другой мир.","explore.body":"Я часто задерживаюсь в фантастике, глубоких историях и экшен-RPG. Прохожу сюжет до конца, но сохраняю и простые моменты: утро Ви, дорогу с попутчиками, финал прохождения. Персонажи и выборы остаются со мной после игры.","game.city":"ГОРОД / СЮЖЕТ","game.action":"ЭКШЕН / ФИЛОСОФИЯ","game.world":"МИР / ИСТОРИЯ","game.puzzle":"ПРОСТРАНСТВО / ЗАГАДКИ","game.space":"ЗВЁЗДЫ / ИССЛЕДОВАНИЕ","explore.cta":"Мои игровые записи на Bilibili","create.title1":"Любимые миры —","create.title2":"в новой форме.","create.body":"Любимого персонажа или мир хочется исследовать в другой форме. Воссоздание двенадцати храмов Saint Seiya в Minecraft и попытки адаптировать референсную модель Камисато Аято для YSM превращают этот интерес в цифровое творчество.","create.detail":"Здесь — записи о воссоздании архитектуры и экспериментах с моделями при помощи ИИ. Референсы, помощь инструментов и собственные попытки имеют разные источники. Скриншоты процесса не означают, что модель завершена или опубликована.","create.youtube":"Канал YouTube","contact.title1":"На связи","contact.title2":"с миром.","contact.intro":"Одно путешествие на разных платформах.","search.label":"Найти платформу или ключевое слово","search.placeholder":"Платформа / слово","channel.code":"КОД / ПРОФИЛЬ","channel.build":"СБОРКИ / АВТОР","channel.watch":"ВИДЕО / ПРОФИЛЬ","channel.social":"ОБЩЕНИЕ / ПРОФИЛЬ","search.empty":"Подходящие каналы не найдены.","search.reset":"Сбросить поиск","channel.note":"Все шесть ссылок ведут на мои страницы. Внешние ссылки открываются в новой вкладке.","guest.title1":"Оставь","guest.title2":"сообщение.","guest.intro1":"Об играх, творчестве — или просто поздоровайся.","guest.intro2":"Любой разговор может стать началом нового пути.","guest.write":"Написать сообщение","guest.notice":"Войдите через GitHub и разрешите доступ, чтобы писать, просматривать и публиковать сообщения здесь. Сообщения публичны. Не указывайте личные данные.","guest.thread":"Открыть обсуждение","guest.editorTitle":"Написать сообщение","guest.connecting":"Подключаем редактор сообщений…","guest.retryEditor":"Подключить редактор снова","guest.readback":"Сообщения и запасные ссылки","guest.refresh":"Обновить сообщения","guest.idle":"Откройте панель, чтобы загрузить сообщения.","guest.empty":"Сообщений пока нет.","guest.first":"Первое сообщение может быть вашим.","guest.public":"Публичные сообщения","guest.more":"Загрузить ещё","guest.order":"По времени публикации · Сообщения хранятся на GitHub","guest.github":"Написать на GitHub","noscript.please":"Пожалуйста, ","noscript.github":"читайте и оставляйте сообщения на GitHub","noscript.note":"Навигация и внешние ссылки доступны, все проекты видны. Для поиска и сообщений на странице нужен JavaScript.","search.heading":"НАЙТИ КАНАЛ","channel.directory":"КАТАЛОГ КАНАЛОВ","hero.scroll":"ЛИСТАЙ ДАЛЬШЕ","footer.top":"НАВЕРХ","lang.label":"Выбрать язык","lang.auto":"Как в браузере","search.count":"КАНАЛЫ: {shown} / {total}","guest.anonymous":"Удалённый пользователь","guest.visitor":"гостя","guest.permalink":"Открыть сообщение {name} на GitHub","guest.loading":"Загружаем сообщения…","guest.rateLimit":"GitHub временно ограничил запросы. Повторите позже или откройте обсуждение на GitHub.","guest.loadError":"Не удалось загрузить сообщения. Повторите запрос или откройте обсуждение на GitHub.","guest.dataError":"Данные сообщений недоступны. Повторите позже.","guest.loaded":"Загружено сообщений: {count}","guest.connected":"Публичный канал подключён.","guest.timeout":"Время ожидания истекло. Повторите запрос или откройте GitHub.","guest.network":"Сеть недоступна. Повторите запрос или откройте GitHub.","guest.ready":"Войдите через GitHub, чтобы писать, просматривать и публиковать ниже.","guest.editorError":"Редактор не подключился. Повторите попытку или используйте запасные ссылки ниже.","records.projects":"Модпаки, механизмы и история сохранения","record.train.kind":"СБОРКА / ЖЕЛЕЗНЫЕ ДОРОГИ","record.train.body":"Сборка вокруг железных дорог Create: механизмы, модели игроков и выживание в одном мире.","record.guided.kind":"МОД / ПЕРВЫЙ ЗАПУСК","record.guided.body":"Стартовый экран с выбором режима и переключателями необязательных модов для авторов сборок.","record.sorcery.kind":"СБОРКА / МЕХАНИЗМЫ И МАГИЯ","record.sorcery.body":"Create 6 и Ars Nouveau: другой ритм выживания между производством, магией и приключениями.","record.modrinth":"Открыть на Modrinth","records.games":"Записи из других миров","record.cyber.kind":"ГЕЙМПЛЕЙ / ИСТОРИЯ","record.cyber.title":"Найт-Сити: концовка «Солнце»","record.cyber.body":"Полная запись концовки «Солнце» в Cyberpunk 2077.","record.nier.title":"NieR:Automata: первое прохождение","record.nier.body":"Финальные моменты первого прохождения NieR:Automata и послевкусие путешествия.","record.watch":"Смотреть видео","create.bilibili":"Bilibili: прохождения, эксперименты и творчество","records.videos":"Архитектура и эксперименты с персонажами","record.series.kind":"СЕРИЯ / ВЫЖИВАНИЕ","record.series.title":"Прохождение Create Train","record.series.body":"Серия о выживании и новых путешествиях по миру сборки.","record.test.kind":"ЭКСПЕРИМЕНТ / СРАВНЕНИЕ","record.test.title":"С C2ME / Без C2ME","record.test.body":"Сравнение загрузки чанков при скоростном полёте. В описании версии на YouTube указаны Minecraft 1.20.1, Forge 47.4.1 и более 270 модов.","record.temple.kind":"ПОСТРОЙКА / ВОССОЗДАНИЕ","record.temple.title":"Двенадцать храмов в Minecraft","record.temple.body":"Архитектура Святилища из Saint Seiya в мире блоков.","tools.tab":"Код и инструменты","tools.title1":"От задачи —","tools.title2":"к инструменту.","tools.body":"Если инструмент неудобен, рабочие процессы не соединяются или возникают проблемы совместимости, я пробую разобраться сам. Здесь — адаптации и исправления из практических задач, с пояснениями для тех, кто будет пользоваться ими дальше.","tools.detail":"Самостоятельные утилиты, адаптации сторонних проектов и эксперименты в форках — разные формы участия. Реализация и источники указаны в репозиториях.","tools.art":"Схема рабочего процесса из узлов и геометрических модулей","tools.github":"Другой открытый код","records.tools":"Тесты, адаптации и исправления","record.browser.kind":"АДАПТАЦИЯ / НА БАЗЕ UPSTREAM","record.browser.body":"Упаковка Browser Use CLI в плагин Codex с инструкциями для Windows PowerShell. Автоматизацию браузера обеспечивают исходные проекты.","record.fixer.kind":"УТИЛИТА / СОВМЕСТИМОСТЬ","record.fixer.body":"Утилита для совместимости вызовов инструментов Gemini с CC Switch в Windows. Подход и использование описаны в репозитории.","record.source":"Код и документация","record.factory.kind":"ДЕМО / МЕХАНИЗМЫ","record.factory.title":"Мобильная фабрика: шасси и привод","record.factory.body":"Если можно возить материалы на фабрику, почему бы не отправить фабрику за ними? Запись о шасси и приводе большой гусеничной передвижной фабрики.","focus.label":"Что для меня важно","focus.browse":"Посмотреть работы направления","focus.build.title":"От одной передачи до целой железной дороги.","focus.build.first.title":"Мир, который работает","focus.build.first.body":"Превратить старую шахтную ветку в воздушную магистраль, прокатиться по лесной линии или отправить фабрику за ресурсами. Мне нравится связывать маршруты, привод и назначение в систему, в которой можно играть.","focus.build.second.title":"Сохранять жизнь игрового мира","focus.build.second.body":"Серия Create Train сохраняет находки замков, полёты, исследования и возвращения домой. Даже годовщина сохранения заслуживает отдельной записи. Хочется дальше строить, играть и сохранять удачные решения вместе с забавными провалами.","focus.explore.title":"Игра закончилась, а путешествие осталось с тобой.","focus.explore.first.title":"Я запоминаю людей в истории","focus.explore.first.body":"В Cyberpunk 2077 мне нравится Панам, а из концовок я предпочитаю «Звезду». Меня привлекает не только масштаб мира, но и персонажи, отношения и чувства, которые остаются после выбора.","focus.explore.second.title":"То, что остаётся после титров","focus.explore.second.body":"Ради истинной концовки PRAGMATA хотелось идти дальше; слова «Пойдём посмотрим на море» остались в памяти. Первый маршрут NieR:Automata оставил другое послевкусие. Пространства Portal 2 и горизонты No Man’s Sky — ещё одно направление того же любопытства.","focus.create.title":"От ступеней Святилища до силуэта модели.","focus.create.first.title":"Знакомый мир из блоков","focus.create.first.body":"Двенадцать храмов соединяют мою любовь к Saint Seiya и Minecraft. Колоннады, лестницы и силуэты дворцов превращают знакомое по истории пространство в место, по которому можно пройти.","focus.create.second.title":"Перенести персонажа в другую игру","focus.create.second.body":"Я пробовал связать Blender и Blockbench с ИИ через MCP и использовать готовые модели и виды персонажа для экспериментов с геометрией, UV и скелетом YSM. Это пока эксперимент: хочется понять возможности инструментов и сохранить ход попыток.","focus.tools.title":"Есть проблема — попробуем её решить.","focus.tools.first.title":"Инструменты для моей рабочей среды","focus.tools.first.body":"Browser Use for Codex — адаптация и упаковка сторонних браузерных инструментов. Мне важно встроить их в повседневную работу и описать особенности использования в Windows PowerShell.","focus.tools.second.title":"Исправить и объяснить, как это сделано","focus.tools.second.body":"CC Switch Gemini Fixer появился из конкретной проблемы совместимости. Сохранённые в репозитории исправление и инструкции превращают затраченные усилия в то, чем можно пользоваться снова.","about.journeys":"Я помню людей из Найт-Сити, возвращаюсь мыслями к концовкам и порой не хочу уходить даже после титров. Меня привлекают фантастика, глубокие истории и системы, которые можно исследовать. От Cyberpunk 2077 до NieR:Automata и PRAGMATA — хочется сохранить и прохождение, и то, что осталось после него.","record.rail.kind":"Сохранение / железная дорога","record.rail.title":"Поездка по воздушной магистрали","record.rail.body":"Перестроена из ранней шахтной ветки. На момент записи: 5 станций, 10 платформ и 8 шестивагонных поездов. Мир глазами пассажира.","record.panam.title":"К башне Арасака вместе с Панам","record.panam.body":"Запись прохождения с Панам и её спутниками. «Звезда» — моя любимая концовка; здесь сохранена часть пути к ней.","record.pragmata.title":"PRAGMATA: после финала","record.pragmata.body":"От предзаказа до прохождения и пути к истинному финалу. «Пойдём посмотрим на море» осталось в памяти. Игра закончилась, а чувства — ещё нет.","record.model.kind":"Эксперимент / модели с помощью ИИ","record.model.title":"Камисато Аято × YSM: попытки адаптации","record.model.body":"Эксперимент с адаптацией для YSM по готовым моделям и видам персонажа при помощи ИИ, Blender и Blockbench. По ссылке — процесс, а не готовая модель для скачивания.","record.process":"Смотреть записи эксперимента","record.reflection":"Читать впечатления","theme.toggle":"Сменить тему","theme.mineral":"МИНЕРАЛ","theme.ivory":"АЙВОРИ"},"zh-Hant":{"meta.description":"HadesScience 的虛擬生活記錄：Create Train、Minecraft 鐵路與建築、遊戲旅程、角色模型和工具實驗。","skip":"跳至正文","home":"HadesScience 首頁","nav.label":"主導覽","nav.manifesto":"關於我","nav.missions":"探索計畫","nav.contact":"聯絡站","nav.guestbook":"留言板","nav.open":"開啟導覽","nav.close":"關閉導覽","hero.kicker":"好奇心，是唯一的推進劑。","hero.intro":"我是 HadesScience。","hero.line1":"在遊戲裡旅行，也親手構築世界。","hero.line2":"把創造、折騰與難忘的片段，留在這裡。","hero.art":"深空藍軌道與橙色圓盤構成的動態航太海報","hero.scrollLabel":"向下閱讀個人介紹","manifesto.caption":"玩家 · 整合包作者 · 數位世界的記錄者","manifesto.title1":"世界很大。","manifesto.title2":"別停在","manifesto.title3":"已知之內。","manifesto.lead1":"有些世界值得走進去。","manifesto.lead2":"有些世界，值得親手建起來。","manifesto.body":"我是 HadesScience，也使用 Milo 這個名字。我是玩家，也是 Minecraft 整合包 Create Train 的作者。鋪鐵路、接傳動、試模組，或只是坐上列車，看自己一點點搭起來的世界從窗外經過——這些都是我的虛擬生活。","manifesto.station":"這裡存放我的虛擬生活：建造與生存、遊戲實況、角色還原，以及讓這些體驗繼續運轉的工具實驗。B 站、YouTube、X 與程式碼儲存庫，記錄著同一個我在不同數位世界裡的足跡。","principle.explore":"EXPLORE / 探索","principle.build":"CONSTRUCT / 構築","principle.create":"REIMAGINE / 重想","missions.caption":"虛擬生活裡的作品、旅程與實驗","missions.intro":"從一份長期遊玩的存檔，到一段捨不得結束的故事，再到一次未必成功的模型實驗。這裡記錄我已經走過的路，也留下繼續折騰的方向。","missions.label":"選擇探索計畫","build.tab":"方塊與機械","explore.tab":"遊戲與旅程","create.tab":"角色與重構","build.art":"深空藍工業構成圖，機械齒輪緩慢轉動","build.title1":"讓想像","build.title2":"開始運轉。","build.body":"Create Train 是我持續開發的 Minecraft 整合包。鐵路、機械動力、自動化與模組生存，是這個世界的骨架；空中路網、移動工廠和一次次探索，則讓存檔慢慢有了自己的歷史。開發整合包，也親自進去玩，是同一件事的兩面。","build.modrinth":"下載 Create Train","build.github":"伺服器端專案","explore.title1":"下一站，","explore.title2":"另一個世界。","explore.body":"科幻、沉浸敘事與動作 RPG，是我經常停留的地方。我會認真走完一段故事，也會保留旅途中普通的一刻：V 的早晨、一段同行、一次通關。遊戲結束以後，人物和選擇留下的感受還會繼續。","game.city":"城市 / 敘事","game.action":"動作 / 哲思","game.world":"世界 / 故事","game.puzzle":"空間 / 解謎","game.space":"星海 / 探索","explore.cta":"觀看 B 站遊戲紀錄","create.title1":"把喜歡的世界，","create.title2":"換一種方式重構。","create.body":"喜歡一個角色或世界，我也會想換一種方式靠近它。在 Minecraft 裡還原《聖鬥士星矢》的黃金十二宮，或嘗試把神里綾人的參考模型轉為 YSM 適用的形式，都是把喜愛變成數位創作的過程。","create.detail":"這裡保留建築還原與 AI 輔助模型實驗的記錄。參考素材、工具輔助和自己的嘗試各有來源；過程中的截圖是探索記錄，不等於模型已經完成或發布。","create.youtube":"YouTube 頻道主頁","contact.title1":"建立","contact.title2":"連結。","contact.intro":"在不同的平台，繼續同一場探索。","search.label":"尋找平台或關鍵字","search.placeholder":"尋找平台 / 關鍵字","channel.code":"CODE / 個人主頁","channel.build":"BUILD / 作者主頁","channel.watch":"WATCH / 個人主頁","channel.social":"SOCIAL / 個人主頁","search.empty":"找不到這個頻道。","search.reset":"重設搜尋","channel.note":"六個平台皆直達個人主頁，所有外部連結在新分頁開啟。","guest.title1":"留下","guest.title2":"一則訊息。","guest.intro1":"關於遊戲、創作，或只是打聲招呼。","guest.intro2":"每一次交流，都可能是新探索的起點。","guest.write":"在這裡留言","guest.notice":"首次留言須完成 GitHub 登入授權，即可在頁內編輯、預覽與發布。留言將公開顯示，請勿填寫私人資訊。","guest.thread":"查看完整討論","guest.editorTitle":"寫一則訊息","guest.connecting":"正在連線至留言編輯器…","guest.retryEditor":"重新連線至留言編輯器","guest.readback":"查看留言清單與備用入口","guest.refresh":"重新整理留言","guest.idle":"展開此區塊以讀取公開留言。","guest.empty":"還沒有留言。","guest.first":"第一則訊息，或許就來自你。","guest.public":"公開留言","guest.more":"繼續載入留言","guest.order":"依發布時間排列 · 留言長期儲存在 GitHub","guest.github":"前往 GitHub 留言","noscript.please":"請","noscript.github":"前往 GitHub 查看與發布留言","noscript.note":"頁面導覽與外部連結皆可使用；探索計畫全部顯示。頻道搜尋及頁內留言讀取須啟用 JavaScript。","search.heading":"尋找頻道","channel.directory":"頻道目錄","hero.scroll":"向下探索","footer.top":"返回頂端","lang.label":"選擇語言","lang.auto":"跟隨瀏覽器","search.count":"{shown} / {total} 個頻道","guest.anonymous":"已註銷使用者","guest.visitor":"訪客","guest.permalink":"在 GitHub 查看 {name} 的留言","guest.loading":"正在讀取公開留言…","guest.rateLimit":"GitHub 暫時限制了讀取頻率。請稍後重試，或前往 GitHub 查看留言。","guest.loadError":"暫時無法讀取留言。請重新整理，或前往 GitHub 查看完整討論。","guest.dataError":"留言資料暫時無法使用，請稍後再試。","guest.loaded":"已讀取 {count} 則公開留言","guest.connected":"公開頻道已連線。","guest.timeout":"讀取逾時。請重新整理，或前往 GitHub 查看留言。","guest.network":"網路暫時無法連線，請重新整理或前往 GitHub 查看留言。","guest.ready":"完成 GitHub 登入授權後，即可在下方編輯、預覽與發布。","guest.editorError":"留言編輯器暫時無法連線。請重試，或展開下方備用入口。","records.projects":"整合包、機械與存檔記錄","record.train.kind":"整合包 / 鐵路與自動化","record.train.body":"以 Create 鐵路為中心，組合機械、角色模型與生存內容，構建可以長期探索的模組世界。","record.guided.kind":"模組 / 啟動引導","record.guided.body":"為整合包製作首次啟動引導、模式選擇與可選模組開關，讓玩家更清楚地選擇自己的體驗。","record.sorcery.kind":"整合包 / 機械與魔法","record.sorcery.body":"讓 Create 6 與 Ars Nouveau 相遇，在機械生產、魔法與冒險之間，尋找另一種生存節奏。","record.modrinth":"在 Modrinth 查看","records.games":"留下來的遊戲片段","record.cyber.kind":"遊戲實況 / 敘事","record.cyber.title":"夜之城，太陽結局","record.cyber.body":"《電馭叛客 2077》太陽結局的完整流程紀錄，保留這一段旅程。","record.nier.title":"NieR:Automata，一周目終點","record.nier.body":"記錄《尼爾：自動人形》第一周目的收尾，關於旅途，也關於餘韻。","record.watch":"觀看影片","create.bilibili":"B 站實況、實驗與創作","records.videos":"建築還原與角色實驗","record.series.kind":"系列 / 生存實況","record.series.title":"Create Train 實況","record.series.body":"從新的征程到繼續開拓，把整合包裡的生存與探索串成連續紀錄。","record.test.kind":"實驗 / 效能對比","record.test.title":"有 C2ME，與沒有 C2ME","record.test.body":"記錄高速飛行時的區塊載入對比。YouTube 版簡介列出 Minecraft 1.20.1、Forge 47.4.1 與 270 多個模組的測試環境。","record.temple.kind":"創作 / 建築還原","record.temple.title":"在 Minecraft 還原黃金十二宮","record.temple.body":"把《聖鬥士星矢》中的聖域建築轉化為方塊世界裡的空間。","tools.tab":"程式碼與工具","tools.title1":"從問題出發，","tools.title2":"做一個工具。","tools.body":"遇到工具不順手、工作流程銜接不上，或相容性出了問題，我也會嘗試自己動手處理。這裡放著一些實際問題帶來的適配與修復，以及留給後來使用者的說明。","tools.detail":"獨立工具、基於上游的適配，以及開源專案的分支實驗，是不同的參與方式。具體實作和來源都留在儲存庫中。","tools.art":"由節點、連線與幾何模組組成的程式工作流程圖","tools.github":"更多公開程式碼","records.tools":"測試、適配與修復記錄","record.browser.kind":"適配 / 基於上游專案","record.browser.body":"將 Browser Use CLI 工作流程封裝為 Codex 外掛，補充 Windows PowerShell 使用說明。瀏覽器能力來自上游專案。","record.fixer.kind":"工具 / 相容性修復","record.fixer.body":"面向 Windows 上的 CC Switch 與 Gemini 工具呼叫相容問題製作的修復工具，原理與使用方式記錄在儲存庫。","record.source":"查看程式碼與說明","record.factory.kind":"演示 / 機械系統","record.factory.title":"移動工廠：底盤與動力","record.factory.body":"既然可以把材料送到工廠，為什麼不能開著工廠去找材料？記錄大型履帶移動工廠的底盤與動力設計。","focus.label":"我在意的事","focus.browse":"瀏覽這個方向的作品","focus.build.title":"從一段傳動，到一整條鐵路。","focus.build.first.title":"讓世界真正運轉起來","focus.build.first.body":"把礦區舊線改成空中高速鐵路，坐上環林線看沿途風景，或者乾脆開著工廠去找材料。比起一件孤立的機器，我更喜歡把線路、動力與用途連成一個能遊玩的系統。","focus.build.second.title":"把存檔裡的日子留下來","focus.build.second.body":"Create Train 實況從發現城堡、飛向遠方，記錄到探索與歸途；存檔一週年也值得單獨留念。接下來仍想繼續建設、繼續遊玩，把成功的設計和意外的翻車都留下。","focus.explore.title":"有些遊戲結束了，旅程還沒有。","focus.explore.first.title":"會記住故事裡的人","focus.explore.first.body":"在《電馭叛客 2077》裡，我喜歡帕南，也偏愛星星結局。吸引我的不只是世界的規模，還有人物、關係與選擇留下的感受。","focus.explore.second.title":"通關以後，仍然想起","focus.explore.second.body":"《PRAGMATA》讓我為真結局繼續努力，也記住了「去看大海吧」；《尼爾：自動人形》的一週目終點，則留下另一種餘韻。解開《傳送門 2》的空間、繼續探索《No Man’s Sky》，也是這份好奇心的去處。","focus.create.title":"從聖域的台階，到模型的輪廓。","focus.create.first.title":"用方塊留住一個熟悉的世界","focus.create.first.body":"黃金十二宮的還原，連接了我對《聖鬥士星矢》和 Minecraft 的喜愛。柱廊、台階與宮殿的輪廓，讓原本在作品裡見過的空間，變成可以自己走進去的地方。","focus.create.second.title":"試著把角色帶進另一個遊戲","focus.create.second.body":"我嘗試讓 AI 透過 MCP 連接 Blender 與 Blockbench，參考既有模型和三視圖，探索 YSM 模型、UV 與骨骼適配。這條路線仍是實驗；想繼續弄清楚工具能做到哪裡，也把嘗試的過程留下。","focus.tools.title":"有個問題，那就試著把它解決。","focus.tools.first.title":"工具要能用在自己的環境裡","focus.tools.first.body":"Browser Use for Codex 是圍繞上游瀏覽器工具做的適配封裝。我關注它如何進入日常工作流程，也整理 Windows PowerShell 下的使用細節。","focus.tools.second.title":"解決了，也把過程說明白","focus.tools.second.body":"CC Switch Gemini Fixer 來自具體的相容問題。把修復方式與使用說明留在儲存庫，是為了讓一次折騰留下可以繼續使用的東西。","about.journeys":"我也會在夜之城記住一個人，為一段結局反覆回味，或在通關後久久不想離開。科幻、沉浸敘事與能自由探索的系統總能吸引我。從《電馭叛客 2077》到《尼爾：自動人形》與《PRAGMATA》，我想留下的不只有通關記錄，還有故事結束後的餘韻。","record.rail.kind":"存檔 / 鐵路運行","record.rail.title":"沉浸式搭乘空中高速鐵路","record.rail.body":"由早期礦區線路改擴建而來。影片記錄時已有 5 站、10 站台，8 列六節編組列車運行；從乘客視角看看這個世界。","record.panam.title":"和帕南一行，前往荒坂塔","record.panam.body":"保留與帕南一行同行的遊戲實況。星星是我偏愛的結局；這段記錄留下走向那個結局的旅程。","record.pragmata.title":"PRAGMATA：通關之後","record.pragmata.body":"從預購到通關，再為真結局繼續努力。「去看大海吧」留在了心裡；遊戲告一段落，感受還沒有。","record.model.kind":"實驗 / AI 輔助模型","record.model.title":"神里綾人 × YSM：適配嘗試","record.model.body":"以既有模型和三視圖為參考，嘗試用 AI、Blender 與 Blockbench 探索 YSM 適配。連結是過程記錄，並非成品下載。","record.process":"查看實驗記錄","record.reflection":"閱讀通關感想","theme.toggle":"切換主題風格","theme.mineral":"深空礦物","theme.ivory":"至上米白"}};
  const storageKey = 'hs-language';
  const supported = Object.keys(messages);

  function matchLocale(value) {
    if (typeof value !== 'string') return null;
    const tag = value.trim().replace(/_/g, '-').toLowerCase();
    const parts = tag.split('-');
    if (parts[0] === 'zh') {
      // Explicit script wins; all Traditional Chinese regions share one locale.
      if (parts.includes('hant')) return 'zh-Hant';
      if (parts.includes('hans')) return 'zh-CN';
      return parts.some(part => ['tw','hk','mo'].includes(part)) ? 'zh-Hant' : 'zh-CN';
    }
    return ['en','ja','ru'].includes(parts[0]) ? parts[0] : null;
  }
  function chooseLocale(preferences) {
    const list = Array.isArray(preferences) ? preferences : [preferences];
    for (const preference of list) {
      const match = matchLocale(preference);
      if (match) return match;
    }
    return 'en';
  }
  // Export the pure language resolver for local verification without browser mocks.
  if (typeof module !== 'undefined' && module.exports) {
    module.exports = {matchLocale, chooseLocale, messages};
    return;
  }
  function readPreference() {
    try {
      const saved = localStorage.getItem(storageKey);
      return supported.includes(saved) ? saved : null;
    } catch { return null; }
  }
  let manualLocale = readPreference();
  let locale = manualLocale || chooseLocale(navigator.languages?.length ? navigator.languages : [navigator.language]);
  function t(key, values = {}) {
    const value = messages[locale]?.[key] ?? messages.en[key] ?? key;
    return value.replace(/\{(\w+)\}/g, (match, name) => String(values[name] ?? match));
  }
  function message(element, key, values = {}) {
    if (!element) return;
    element.dataset.i18nMessage = key;
    element.dataset.i18nValues = JSON.stringify(values);
    element.textContent = t(key, values);
  }
  function apply() {
    document.documentElement.lang = locale;
    document.querySelectorAll('[data-i18n-nodes]').forEach(element => {
      if (element.hasAttribute('data-i18n-runtime')) return;
      const keys = JSON.parse(element.dataset.i18nNodes);
      const nodes = Array.from(element.childNodes).filter(node => node.nodeType === Node.TEXT_NODE && node.textContent.trim());
      keys.forEach((key, index) => {
        if (!key || !nodes[index]) return;
        const text = nodes[index].textContent;
        nodes[index].textContent = (text.match(/^\s*/)?.[0] || '') + t(key) + (text.match(/\s*$/)?.[0] || '');
      });
    });
    document.querySelectorAll('[data-i18n-attrs]').forEach(element => {
      const attrs = JSON.parse(element.dataset.i18nAttrs);
      Object.entries(attrs).forEach(([attribute, key]) => element.setAttribute(attribute, t(key)));
    });
    document.querySelectorAll('[data-i18n-message]').forEach(element => {
      message(element, element.dataset.i18nMessage, JSON.parse(element.dataset.i18nValues || '{}'));
    });
    const selector = document.getElementById('language-select');
    if (selector) selector.value = manualLocale || 'auto';
  }
  function setLocale(value) {
    manualLocale = supported.includes(value) ? value : null;
    try {
      if (manualLocale) localStorage.setItem(storageKey, manualLocale);
      else localStorage.removeItem(storageKey);
    } catch {}
    locale = manualLocale || chooseLocale(navigator.languages?.length ? navigator.languages : [navigator.language]);
    apply();
    document.dispatchEvent(new CustomEvent('hs-language-change', {detail:{locale}}));
  }
  window.I18n = {t, message, setLocale, chooseLocale, get locale() { return locale; }};
  apply();
  document.getElementById('language-select')?.addEventListener('change', event => setLocale(event.target.value));
  window.addEventListener('languagechange', () => { if (!manualLocale) setLocale('auto'); });
})();
